DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `am_time_in` timestamp NULL DEFAULT NULL,
  `am_time_out` timestamp NULL DEFAULT NULL,
  `pm_time_in` timestamp NULL DEFAULT NULL,
  `pm_time_out` timestamp NULL DEFAULT NULL,
  `scan_time` timestamp NULL DEFAULT NULL,
  `checkout_time` timestamp NULL DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'present',
  `slot_statuses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`slot_statuses`)),
  `fine_amount` decimal(8,2) NOT NULL DEFAULT 0.00,
  `fine_paid` tinyint(1) NOT NULL DEFAULT 0,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `distance_meters` decimal(8,2) DEFAULT NULL,
  `device_credential` varchar(255) DEFAULT NULL,
  `is_offline_sync` tinyint(1) NOT NULL DEFAULT 0,
  `override_by` bigint(20) unsigned DEFAULT NULL,
  `override_reason` text DEFAULT NULL,
  `verification_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`verification_data`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_event_id_user_id_unique` (`event_id`,`user_id`),
  KEY `attendance_override_by_foreign` (`override_by`),
  KEY `attendance_event_id_status_index` (`event_id`,`status`),
  KEY `attendance_user_id_status_index` (`user_id`,`status`),
  CONSTRAINT `attendance_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `attendance_override_by_foreign` FOREIGN KEY (`override_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `attendance_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `attendance_sync_records`;
